from pathlib import Path
log_file = Path("auth.log")  # Use a log file you are authorized to inspect
keywords = ("failed", "invalid password", "authentication failure")
if log_file.exists():
    for number, line in enumerate(log_file.read_text(errors="replace").splitlines(), 1):
        if any(word in line.lower() for word in keywords):
            print(f"{number}: {line}")

